const boneArcherSheet=new Image();boneArcherSheet.assetSrc='assets/bone-archer-v2.png';
function beginBoneArcher(e){let center={x:p.x,y:p.y},angle=Math.atan2(e.y-p.y,e.x-p.x);e.state='attack';e.elapsed=0;e.struck=false;e.attack={pattern:'boneConvergence',bespoke:true,windup:1.2,origin:{x:e.x,y:e.y},center,hit:false,fired:false,arrows:Array.from({length:6},(_,i)=>{let a=angle+i*Math.PI/3,ux=Math.cos(a),uy=Math.sin(a),x=center.x+ux*240,y=center.y+uy*240;return {ux,uy,x,y,blocked:!passable(x,y,8)||!lineClear(e,{x,y})};})};}
function boneArcherContact(point,from,to){let dx=to.x-from.x,dy=to.y-from.y,l=dx*dx+dy*dy,t=l?Math.max(0,Math.min(1,((point.x-from.x)*dx+(point.y-from.y)*dy)/l)):0,q={x:from.x+dx*t,y:from.y+dy*t};return dist(point,q)<=14+1e-8&&lineClear(q,point);}
function advanceBoneConvergence(a,before,after){if(after<1.2||before>=2.4)return;let radius=240*Math.max(0,1-(after-1.2)/1.2);for(let arrow of a.arrows){if(arrow.blocked)continue;let start={x:arrow.x,y:arrow.y},target={x:a.center.x+arrow.ux*radius,y:a.center.y+arrow.uy*radius},length=dist(start,target),steps=Math.max(1,Math.ceil(length/6)),end={...start};for(let n=1;n<=steps;n++){let q={x:start.x+(target.x-start.x)*n/steps,y:start.y+(target.y-start.y)*n/steps};if(!passable(q.x,q.y,8)||!lineClear(end,q,8)){arrow.blocked=true;break;}end=q;}arrow.x=end.x;arrow.y=end.y;if(!a.hit&&!(p.inv>0)&&boneArcherContact(p,start,end)){hurt(78);a.hit=true;}}}
const boneArcherAnimateBase=animateEnemy;animateEnemy=(e,dt)=>{
 if(e.species!=='r10e3')return boneArcherAnimateBase(e,dt);if(e.hp<=0||e.reactionStun>0||paused||dead||!Number.isFinite(dt)||dt<=0)return;e.anim+=dt;e.flash=Math.max(0,(e.flash||0)-dt);e.slow=Math.max(0,(e.slow||0)-dt);let a=e.attack;
 if(a?.pattern!=='boneConvergence'){e.t-=dt;e.nav=(e.nav||0)-dt;let d=dist(e,p),clear=lineClear(e,p);if(e.t<=0&&d<=420&&clear){beginBoneArcher(e);return;}e.state='idle';if(d>800&&!e.aware||d<=280&&clear)return;if(e.nav<=0){e.nav=.8;e.path=clear?[{x:p.x,y:p.y}]:findPath(e,p);}let to=e.path?.[0];if(to){let dx=to.x-e.x,dy=to.y-e.y,len=Math.hypot(dx,dy);if(len<10)e.path.shift();else{let step=Math.min(len,78*(e.slow>0?.35:1)*dt);e.state=moveActor(e,dx/len*step,dy/len*step,18)>.1?'walk':'idle';e.facing=dx-dy<0?-1:1;}}return;}
 if(dist(e,a.origin)>24){e.attack=null;e.state='idle';e.t=1.5;return;}let before=e.elapsed;e.elapsed=Math.round((e.elapsed+dt)*1e6)/1e6;if(!a.fired&&e.elapsed>=1.2){a.fired=true;e.struck=true;playSound('arrow',e.x,e.y);}advanceBoneConvergence(a,before,e.elapsed);if(e.elapsed>=3.4){e.attack=null;e.state='idle';e.t=3.2;}
};
const boneArcherDrawBase=drawRegionEnemy;drawRegionEnemy=(e,size)=>{if(e.species!=='r10e3'||!boneArcherSheet.complete||!boneArcherSheet.naturalWidth||!boneArcherSheet.naturalHeight)return boneArcherDrawBase(e,size);let f=spriteFrame(e.state,e.anim||0);if(e.hp<=0)f={row:2,col:3};else if(e.attack?.pattern==='boneConvergence')f={row:2,col:e.elapsed<.6?0:e.elapsed<1.2?1:e.elapsed<1.45?2:3};let q=project(e.x,e.y),sw=boneArcherSheet.naturalWidth/4,sh=boneArcherSheet.naturalHeight/3,w=225,h=w*sh/sw,anchor=[[.9,.9,.9,.9],[.85,.85,.83,.84],[.85,.85,.85,.85]][f.row][f.col];ctx.save();ctx.translate(q.x,q.y);ctx.scale(e.facing||1,1);ctx.filter=e.flash>0?'brightness(1.8)':'none';if(typeof drawPreparedEnemySprite==='function')drawPreparedEnemySprite(ctx,boneArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);else ctx.drawImage(boneArcherSheet,f.col*sw,f.row*sh,sw,sh,-w/2,-h*anchor,w,h);ctx.restore();return true;};
const boneArcherSizeBase=enemyVisualSize;enemyVisualSize=e=>e.species==='r10e3'?175:boneArcherSizeBase(e);
const boneArcherGroundBase=drawGroundEffects;drawGroundEffects=()=>{boneArcherGroundBase();for(let e of (typeof enemyRenderList==='function'?enemyRenderList('r10e3'):enemies)){let a=e.attack;if(e.species!=='r10e3'||e.hp<=0||a?.pattern!=='boneConvergence'||e.elapsed>2.6||!visibleAt(a.center.x,a.center.y))continue;let center=project(a.center.x,a.center.y);groundRing(a.center.x,a.center.y,18,'#a4e6d8',2);ctx.save();for(let arrow of a.arrows){if(arrow.blocked)continue;let q=project(arrow.x,arrow.y);ctx.strokeStyle=a.fired?'#e0fff4':'#739f97';ctx.lineWidth=a.fired?3:1;ctx.beginPath();ctx.moveTo(q.x,q.y);if(!a.fired){ctx.lineTo(center.x,center.y);}else{let tail=project(arrow.x+arrow.ux*24,arrow.y+arrow.uy*24);ctx.lineTo(tail.x,tail.y);let left=project(arrow.x+arrow.ux*9-arrow.uy*6,arrow.y+arrow.uy*9+arrow.ux*6),right=project(arrow.x+arrow.ux*9+arrow.uy*6,arrow.y+arrow.uy*9-arrow.ux*6);ctx.moveTo(left.x,left.y);ctx.lineTo(q.x,q.y);ctx.lineTo(right.x,right.y);}ctx.stroke();}ctx.restore();}};
if(typeof registerDirectEnemy==='function')registerDirectEnemy('r10e3',animateEnemy,drawRegionEnemy);
